// Package: Azure.Storage.Files.Shares
// Install: dotnet add package Azure.Storage.Files.Shares

using Azure.Storage.Files.Shares;

public class FileShareService
{
    private readonly ShareClient _share;

    public FileShareService(string connectionString, string shareName = "app-files")
    {
        var shareUri = new Uri($"https://demostorageaccount.file.core.windows.net/{shareName}");
        _share = new ShareClient(shareUri, new DefaultAzureCredential());
    }

    public async Task UploadAsync(string localPath, string fileName, string directoryName = "exports", CancellationToken ct = default)
    {
        try
        {
            await _share.CreateIfNotExistsAsync(cancellationToken: ct);
            var directory = _share.GetDirectoryClient(directoryName);
            await directory.CreateIfNotExistsAsync(cancellationToken: ct);

            var fileClient = directory.GetFileClient(fileName);
            await fileClient.UploadAsync(localPath, overwrite: true, ct);
            Console.WriteLine($"Uploaded {fileName} to share '{_share.Name}/{directoryName}'");
        }
        catch (RequestFailedException ex)
        {
            Console.WriteLine($"Upload failed: {ex.Message}");
            throw;
        }
    }

    public async Task DownloadAsync(string fileName, string destinationPath, string directoryName = "exports", CancellationToken ct = default)
    {
        try
        {
            var directory = _share.GetDirectoryClient(directoryName);
            var fileClient = directory.GetFileClient(fileName);
            var download = await fileClient.DownloadAsync(ct);
            await using var stream = File.OpenWrite(destinationPath);
            await download.Value.Content.CopyToAsync(stream, ct);
            Console.WriteLine($"Downloaded {fileName} to {destinationPath}");
        }
        catch (RequestFailedException ex) when (ex.Status == 404)
        {
            Console.WriteLine($"File {fileName} not found in share");
            throw;
        }
    }
}

// Usage
var service = new FileShareService("DefaultEndpointsProtocol=https;AccountName=demostorageaccount;...");
await service.UploadAsync("customers.csv", "customers.csv");
await service.DownloadAsync("customers.csv", "customers-copy.csv");

// Expected output:
// Uploaded customers.csv to share 'app-files/exports'
// Downloaded customers.csv to customers-copy.csv
